import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Dashboard = () => {
  const [threatData, setThreatData] = useState(null);
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchThreats = async () => {
    try {
      // Test Traffic Data (Sending to ML Service)
      const res = await axios.post('http://localhost:8000/analyze-traffic', {
        ip_source: `192.168.1.${Math.floor(Math.random() * 255)}`,
        packet_size: Math.floor(Math.random() * 8000),
        request_count: Math.floor(Math.random() * 2000)
      });

      setThreatData(res.data);
      setLoading(false);

      if (res.data.is_anomaly) {
        // Naya alert top par add karein
        setAlerts(prev => [{
          id: Date.now(),
          ...res.data,
          time: new Date().toLocaleTimeString()
        }, ...prev].slice(0, 8)); // Sirf latest 8 alerts dikhao
      }
    } catch (err) {
      console.error("SOC Engine Offline", err);
    }
  };

  useEffect(() => {
    const timer = setInterval(fetchThreats, 4000); // Har 4 second mein scan
    return () => clearInterval(timer);
  }, []);

  return (
    <div style={{ backgroundColor: '#010409', color: '#c9d1d9', minHeight: '100vh', padding: '30px', fontFamily: 'Segoe UI' }}>

      {/* HEADER SECTION */}
      <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #30363d', paddingBottom: '20px' }}>
        <h2 style={{ color: '#58a6ff' }}>🛡️ CyberGuard AI | Vision 2030 SOC</h2>
        <div style={{ textAlign: 'right' }}>
          <span style={{ color: '#3fb950' }}>● System Live</span>
          <p style={{ fontSize: '12px' }}>Region: Middle East (UAE/KSA)</p>
        </div>
      </div>

      {/* LIVE MONITORING CARDS */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginTop: '20px' }}>
        <div style={{ background: '#0d1117', border: '1px solid #30363d', padding: '20px', borderRadius: '12px' }}>
          <h4>Current Traffic Analysis</h4>
          {loading ? <p>Initializing Sensors...</p> : (
            <>
              <p>Node: <strong>{threatData.location}</strong></p>
              <p>Status: <span style={{ color: threatData.is_anomaly ? '#ff7b72' : '#3fb950' }}>
                {threatData.is_anomaly ? '⚠️ ANOMALY DETECTED' : '✅ SECURE'}
              </span></p>
            </>
          )}
        </div>

        <div style={{ background: '#0d1117', border: '1px solid #30363d', padding: '20px', borderRadius: '12px' }}>
          <h4>AI Recommendation</h4>
          <p style={{ color: '#8b949e' }}>Action: {threatData?.recommendation || 'Monitoring...'}</p>
          <button style={{ background: '#238636', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '6px', cursor: 'pointer' }}>
            Authorize Firewall Block
          </button>
        </div>
      </div>

      {/* THREAT LOG TABLE */}
      <div style={{ marginTop: '30px', background: '#0d1117', border: '1px solid #30363d', borderRadius: '12px', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead style={{ background: '#161b22', color: '#8b949e' }}>
            <tr>
              <th style={{ padding: '15px' }}>Timestamp</th>
              <th style={{ padding: '15px' }}>Severity</th>
              <th style={{ padding: '15px' }}>Type</th>
              <th style={{ padding: '15px' }}>Node Location</th>
            </tr>
          </thead>
          <tbody>
            {alerts.map(alert => (
              <tr key={alert.id} style={{ borderBottom: '1px solid #30363d' }}>
                <td style={{ padding: '15px', fontSize: '13px' }}>{alert.time}</td>
                <td style={{ padding: '15px' }}>
                  <span style={{ 
                    padding: '4px 8px', borderRadius: '12px', fontSize: '11px', fontWeight: 'bold',
                    background: alert.threat_level === 'Critical' ? '#490000' : '#3b2300',
                    color: alert.threat_level === 'Critical' ? '#ffa1a1' : '#ffab70'
                  }}>
                    {alert.threat_level.toUpperCase()}
                  </span>
                </td>
                <td style={{ padding: '15px' }}>{alert.analysis_report}</td>
                <td style={{ padding: '15px' }}>{alert.location}</td>
              </tr>
            ))}
          </tbody>
        </table>
        {alerts.length === 0 && <p style={{ padding: '20px', textAlign: 'center' }}>No threats detected in the last scan cycles.</p>}
      </div>
    </div>
  );
};

export default Dashboard;
